CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','corrector','docente','recepcion')),active INTEGER NOT NULL DEFAULT 1,must_change_password INTEGER NOT NULL DEFAULT 0,token_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(sid TEXT PRIMARY KEY,data TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expires ON sessions(expires);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT NOT NULL,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id TEXT PRIMARY KEY,user_uid TEXT NOT NULL,student_code TEXT NOT NULL,name_snapshot TEXT NOT NULL,cycle_snapshot TEXT NOT NULL,shift_snapshot TEXT NOT NULL,business_date TEXT NOT NULL,arrival_time TEXT,arrived_at TEXT,status TEXT NOT NULL,justification TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'scanner',UNIQUE(user_uid,business_date,shift_snapshot));
CREATE INDEX IF NOT EXISTS attendance_date_cycle ON attendance(business_date,cycle_snapshot);
CREATE TABLE IF NOT EXISTS contacts(id TEXT PRIMARY KEY,user_uid TEXT NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL,consent INTEGER NOT NULL DEFAULT 0,consented_at TEXT,active INTEGER NOT NULL DEFAULT 1,UNIQUE(user_uid,phone));
CREATE TABLE IF NOT EXISTS grade_history(id INTEGER PRIMARY KEY,evaluation_id TEXT NOT NULL,student_code TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS grade_history_lookup ON grade_history(evaluation_id,student_code);
CREATE TABLE IF NOT EXISTS evaluation_revisions(evaluation_id TEXT NOT NULL,revision INTEGER NOT NULL,definition TEXT NOT NULL,key_snapshot TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(evaluation_id,revision));
CREATE TABLE IF NOT EXISTS exam_templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,definition TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS omr_sheets(id TEXT PRIMARY KEY,evaluation_id TEXT NOT NULL,student_code TEXT NOT NULL,area TEXT NOT NULL DEFAULT '',form TEXT NOT NULL DEFAULT 'A',revision INTEGER NOT NULL,layout_version INTEGER NOT NULL DEFAULT 2,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY,evaluation_id TEXT NOT NULL,revision INTEGER NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',files TEXT NOT NULL DEFAULT '[]',result TEXT NOT NULL DEFAULT '{}',error TEXT NOT NULL DEFAULT '',actor TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS import_batches_status ON import_batches(status,created_at);
CREATE TABLE IF NOT EXISTS imported_sheets(sheet_id TEXT NOT NULL,page INTEGER NOT NULL,batch_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(sheet_id,page));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,event_key TEXT NOT NULL UNIQUE,recipient TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER NOT NULL DEFAULT 0,provider_id TEXT,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS outbox_provider ON outbox(provider_id);
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS respuesta_evaluacion_lookup ON respuestas_evaluacion(evaluacion_id,puntajeTotal DESC);
CREATE INDEX IF NOT EXISTS respuesta_estudiante_lookup ON respuestas_evaluacion(codigoEstudiante);
CREATE INDEX IF NOT EXISTS registros_tarea_lookup ON registros_tarea(tarea_id,codigoEstudiante);
CREATE TABLE IF NOT EXISTS exam_roster(evaluation_id TEXT NOT NULL,user_uid TEXT NOT NULL,code_snapshot TEXT NOT NULL,name_snapshot TEXT NOT NULL,cycle_snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(evaluation_id,user_uid));
